using GastricCancerDetection.Application.Interfaces; using GastricCancerDetection.Infrastructure.Persistence; using Microsoft.EntityFrameworkCore;
namespace GastricCancerDetection.Infrastructure.Services; public class CandidateScoringService:ICandidateScoringService { private readonly GastricCancerDbContext _db; public CandidateScoringService(GastricCancerDbContext db)=>_db=db; public async Task RankAsync(int runId,CancellationToken ct=default){var cs=await _db.Candidates.Where(x=>x.AnalysisRunId==runId).ToListAsync(ct); foreach(var c in cs){var bio=c.BiologicalEvidence??0;var stat=c.StatisticalRobustness??0;var ws=c.LiteratureWhitespace??0;var vg=c.ValidationGap??0;var early=c.EarlyStageScore??0;var spec=c.CancerSpecificityScore??0;var cf=c.CfDNADetectabilityScore??0;c.OverallPriority=.20*bio+.15*stat+.15*ws+.15*vg+.15*early+.10*spec+.10*cf;} await _db.SaveChangesAsync(ct);} }
